public class DailyQuota {
    private final int limit;
    private final AtomicInteger used = new AtomicInteger();

    public DailyQuota(int limit) { this.limit = limit; }

    public boolean tryConsume() {
        if (used.get() < limit) {
            used.incrementAndGet();
            return true;
        }
        return false;
    }
}

// Test: 16 thread, mỗi thread gọi tryConsume() 10.000 lần,
// đếm số lần được phép trong một AtomicInteger granted.

fix.code:
public boolean tryConsume() {
    int current;
    do {
        current = used.get();
        if (current >= limit) return false;
    } while (!used.compareAndSet(current, current + 1));
    return true;
}

// Cùng ý, gọn hơn (Java 8+). Hàm có thể chạy nhiều lần: không đặt side effect trong đó.
public boolean tryConsume() {
    int before = used.getAndUpdate(n -> n < limit ? n + 1 : n);
    return before < limit;
}
